tasks.solution:
def missing_share(values):
    if not values:
        return None
    return sum(v is None for v in values) / len(values)

def repeated_ids(ids):
    seen = set()
    repeated = set()
    for key in ids:
        if key in seen:
            repeated.add(key)
        seen.add(key)
    return sorted(repeated)

def utc_day(iso_time):
    from datetime import datetime, timezone
    value = datetime.fromisoformat(iso_time)
    return value.astimezone(timezone.utc).date().isoformat()

def zone_counts(rows):
    out = {}
    for zone, duration in rows:
        total, known = out.get(zone, (0,0))
        out[zone] = (total + 1, known + int(duration is not None))
    return out

def unique_lookup(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise ValueError('Повтор ключа')
        out[key] = value
    return out

