def running_amounts(rows):
    totals = {}
    out = []
    for zone, amount in rows:
        totals[zone] = totals.get(zone, 0) + amount
        out.append(totals[zone])
    return out

def pivot_totals(rows):
    out = {}
    for day, zone, amount in rows:
        per_day = out.setdefault(day, {})
        per_day[zone] = per_day.get(zone, 0) + amount
    return out

